public class Order {
    private final OrderId id;
    private final CustomerId customerId;
    private final List<OrderLine> lines;
    private OrderStatus status;
    private final List<DomainEvent> domainEvents;

    // Private constructor - use factory or reconstitute from repo
    private Order(OrderId id, CustomerId customerId) {
        this.id = id;
        this.customerId = customerId;
        this.lines = new ArrayList<>();
        this.status = OrderStatus.DRAFT;
        this.domainEvents = new ArrayList<>();
    }

    // Factory method
    public static Order create(OrderId id, CustomerId customerId) {
        Order order = new Order(id, customerId);
        return order;
    }

    // Business method - enforces invariants
    public void addLine(ProductId productId, Quantity quantity, Money unitPrice) {
        if (status.isShippedOrLater()) {
            throw new OrderAlreadyShippedException(
                "Cannot modify order " + id + " after shipping");
        }

        OrderLine line = new OrderLine(productId, quantity, unitPrice);
        lines.add(line);
    }

    public void removeLine(ProductId productId) {
        if (status.isShippedOrLater()) {
            throw new OrderAlreadyShippedException(
                "Cannot modify order " + id + " after shipping");
        }

        lines.removeIf(line -> line.hasProduct(productId));
    }

    public void place() {
        if (lines.isEmpty()) {
            throw new EmptyOrderException("Cannot place empty order");
        }

        if (!status.equals(OrderStatus.DRAFT)) {
            throw new InvalidOrderStateException(
                "Can only place orders in DRAFT status");
        }

        this.status = OrderStatus.PLACED;

        // Publish domain event
        domainEvents.add(new OrderPlaced(id, customerId, 
            calculateTotal(), Instant.now()));
    }

    public void markAsShipped(TrackingNumber trackingNumber) {
        if (!status.equals(OrderStatus.CONFIRMED)) {
            throw new InvalidOrderStateException(
                "Can only ship CONFIRMED orders");
        }

        this.status = OrderStatus.SHIPPED;

        domainEvents.add(new OrderShipped(id, trackingNumber, 
            Instant.now()));
    }

    public Money calculateTotal() {
        return lines.stream()
            .map(OrderLine::getSubtotal)
            .reduce(Money.ZERO, Money::add);
    }

    // Query methods
    public OrderId getId() { return id; }
    public OrderStatus getStatus() { return status; }
    public List<OrderLine> getLines() { 
        return Collections.unmodifiableList(lines); 
    }

    public List<DomainEvent> getDomainEvents() {
        return Collections.unmodifiableList(domainEvents);
    }

    public void clearDomainEvents() {
        domainEvents.clear();
    }
}
```

