// Value Object
public class OrderId {
    private final UUID value;

    public OrderId(UUID value) {
        this.value = Objects.requireNonNull(value);
    }

    public static OrderId generate() {
        return new OrderId(UUID.randomUUID());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof OrderId)) return false;
        OrderId orderId = (OrderId) o;
        return value.equals(orderId.value);
    }

    @Override
    public int hashCode() {
        return Objects.hash(value);
    }
}

// Entity (part of Order aggregate)
public class OrderLine {
    private final ProductId productId;
    private final Quantity quantity;
    private final Money unitPrice;

    public OrderLine(ProductId productId, Quantity quantity, 
                     Money unitPrice) {
        this.productId = Objects.requireNonNull(productId);
        this.quantity = Objects.requireNonNull(quantity);
        this.unitPrice = Objects.requireNonNull(unitPrice);

        if (quantity.isZeroOrNegative()) {
            throw new InvalidQuantityException(
                "Quantity must be positive");
        }
    }

    public Money getSubtotal() {
        return unitPrice.multiply(quantity.value());
    }

    public boolean hasProduct(ProductId productId) {
        return this.productId.equals(productId);
    }
}

// Enum for status (with domain logic)
public enum OrderStatus {
    DRAFT, PLACED, CONFIRMED, SHIPPED, DELIVERED, CANCELLED;

    public boolean isShippedOrLater() {
        return this == SHIPPED || this == DELIVERED;
    }
}

